rule sql_database_dump {
  meta: rule_name = "sql_database_dump";
  description = "Detects unauthorized database dump on production SQL server";
  author = "[Your Name]";
  date = "2024-07-26";
  hash = "072d6df9";
  classification = "critical";
  tags = "data_exfiltration, unauthorized_access";
  scope = category: database;
  reference = ["https://example.com/sql_database_dump"];
  enable = true;

  selection: sel = process(name = "mysqldump") and file(name = "system_backup.sql.gz") and file(md5 = "072d6df9");

  condition: condition = true;
}

